// ClipboardMonitor.swift — polls NSPasteboard.general and stores new clips in ClipStore.

import AppKit
import DittoCore

@MainActor
final class ClipboardMonitor: ClipboardMonitoring {
    unowned let state: AppState

    /// Markers that mean "don't record this" (password managers, transient / generated content).
    static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    /// Types we read explicitly (or that are legacy/derived duplicates) and so never store as "extra" types.
    private static let handledTypes: Set<String> = [
        ClipUTI.plainText, ClipUTI.rtf, ClipUTI.html, ClipUTI.png, ClipUTI.tiff, ClipUTI.fileURL,
        "public.utf16-plain-text", "public.utf16-external-plain-text", "public.utf8-tab-separated-values-text",
        "NSStringPboardType", "NeXT Rich Text Format v1.0 pasteboard type", "Apple HTML pasteboard type",
        "NSFilenamesPboardType", "Apple PNG pasteboard type", "NeXT TIFF v4.0 pasteboard type",
        "Apple URL pasteboard type", "CorePasteboardFlavorType 0x75726C20", "public.url", "public.url-name",
        "com.apple.pasteboard.promised-file-url", "com.apple.pasteboard.promised-file-content-type",
        "com.apple.NSFilePromiseItemMetaData", "com.apple.webarchive", "Apple Web Archive pasteboard type",
        "org.dittomac.internal",
    ]

    /// Full-formatting set (Settings.keepFullFormatting): pasteboard type read → type stored. Kept byte for byte.
    static let fullFormattingSources: [(read: String, store: String)] = [
        (ClipUTI.webArchive, ClipUTI.webArchive), (ClipUTI.legacyWebArchive, ClipUTI.webArchive),
        (ClipUTI.flatRTFD, ClipUTI.flatRTFD), (ClipUTI.rtfd, ClipUTI.rtfd),
        (ClipUTI.jpeg, ClipUTI.jpeg), (ClipUTI.gif, ClipUTI.gif), (ClipUTI.heic, ClipUTI.heic), (ClipUTI.pdf, ClipUTI.pdf),
        (ClipUTI.url, ClipUTI.url), (ClipUTI.urlName, ClipUTI.urlName),
    ]
    /// A single full-formatting format larger than this is skipped (the clip's other formats are still stored).
    static let maxRichFormatBytes = 64 * 1024 * 1024
    /// Rich formats larger than this aren't parsed to derive a plain-text description.
    static let maxDeriveTextBytes = 16 * 1024 * 1024

    private var timer: Timer?
    private var lastChangeCount: Int
    private var ignoredUpTo: Int = -1
    private var pendingCapture: DispatchWorkItem?
    private var captureGroup: (id: Int64, until: Date)?

    var isConnected: Bool {
        get { state.settings.connectedToClipboard }
        set {
            guard newValue != state.settings.connectedToClipboard else { return }
            state.settings.connectedToClipboard = newValue
            // Don't capture what was copied while disconnected.
            lastChangeCount = NSPasteboard.general.changeCount
            NotificationCenter.default.post(name: .dittoConnectionChanged, object: nil)
        }
    }

    init(state: AppState) {
        self.state = state
        self.lastChangeCount = NSPasteboard.general.changeCount
    }

    func start() {
        guard timer == nil else { return }
        let t = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.poll() }
        }
        t.tolerance = 0.1
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    // MARK: ClipboardMonitoring

    func captureNextClip(intoGroup groupID: Int64, until: Date) {
        captureGroup = (groupID, until)
    }

    func saveCurrentClipboard() {
        pendingCapture?.cancel()
        let app = NSWorkspace.shared.frontmostApplication
        lastChangeCount = NSPasteboard.general.changeCount
        if capture(force: true, app: app) {
            state.message("Saved current clipboard")
        } else {
            state.message("Nothing to save from the clipboard")
        }
    }

    func ignoreChangeCount(_ count: Int) {
        ignoredUpTo = max(ignoredUpTo, count)
    }

    // MARK: Polling

    private func poll() {
        let pb = NSPasteboard.general
        let cc = pb.changeCount
        guard cc != lastChangeCount else { return }
        lastChangeCount = cc
        guard isConnected, cc > ignoredUpTo else { return }
        let app = NSWorkspace.shared.frontmostApplication
        pendingCapture?.cancel()
        let delay = state.settings.saveClipDelayMS
        if delay <= 0 {
            _ = capture(force: false, app: app)
            return
        }
        let work = DispatchWorkItem { [weak self] in
            MainActor.assumeIsolated {
                guard let self, NSPasteboard.general.changeCount == cc else { return }
                _ = self.capture(force: false, app: app)
            }
        }
        pendingCapture = work
        // Upstream waits briefly so the source app finishes writing every format.
        DispatchQueue.main.asyncAfter(deadline: .now() + .milliseconds(min(delay, 2000)), execute: work)
    }

    // MARK: Capture

    /// Reads the pasteboard and stores a clip. Returns true when something was stored (or bumped).
    @discardableResult
    private func capture(force: Bool, app: NSRunningApplication?) -> Bool {
        let settings = state.settings
        let pb = NSPasteboard.general
        guard let types = pb.types, !types.isEmpty else { return false }
        let typeNames = Set(types.map(\.rawValue))
        if !typeNames.isDisjoint(with: Self.skipTypes) { return false }
        if !force, typeNames.contains(dittoInternalPasteboardType.rawValue) { return false }

        let bundleID = app?.bundleIdentifier ?? ""
        let appName = app?.localizedName ?? ""
        if !force {
            let include = settings.copyAppInclude.trimmingCharacters(in: .whitespaces)
            if !include.isEmpty, include != "*",
               !(CopyRuleEngine.wildcardMatch(include, bundleID) || CopyRuleEngine.wildcardMatch(include, appName)) {
                return false
            }
            let exclude = settings.copyAppExclude.trimmingCharacters(in: .whitespaces)
            if !exclude.isEmpty,
               CopyRuleEngine.wildcardMatch(exclude, bundleID) || CopyRuleEngine.wildcardMatch(exclude, appName) {
                return false
            }
        }

        let enabled = Set(settings.enabledTypes)
        let all = settings.supportAllTypes
        func wants(_ t: String) -> Bool { all || enabled.contains(t) }

        var formats: [ClipFormat] = []
        var text: String?
        var fileNames: [String] = []
        var imageSize: NSSize?

        if wants(ClipUTI.plainText), let s = pb.string(forType: .string), !s.isEmpty {
            text = s
            formats.append(ClipFormat(type: ClipUTI.plainText, data: Data(s.utf8)))
        }
        if wants(ClipUTI.rtf), let d = pb.data(forType: .rtf), !d.isEmpty {
            formats.append(ClipFormat(type: ClipUTI.rtf, data: d))
        }
        if wants(ClipUTI.html), let d = pb.data(forType: .html), !d.isEmpty {
            formats.append(ClipFormat(type: ClipUTI.html, data: d))
        }
        if wants(ClipUTI.png) || wants(ClipUTI.tiff) {
            if let d = pb.data(forType: .png), !d.isEmpty {
                formats.append(ClipFormat(type: ClipUTI.png, data: d))
                imageSize = NSBitmapImageRep(data: d)?.size
            } else if let d = pb.data(forType: .tiff), let rep = NSBitmapImageRep(data: d),
                      let png = rep.representation(using: .png, properties: [:]) {
                formats.append(ClipFormat(type: ClipUTI.png, data: png))
                imageSize = NSSize(width: rep.pixelsWide, height: rep.pixelsHigh)
            }
        }
        // Full formatting: web archives (HTML + embedded images), RTFD (text with inline images), JPEG/GIF/HEIC,
        // PDF and links, independent of the enabled-types list.
        var richTypes = Set<String>()
        if settings.keepFullFormatting {
            for (read, storeAs) in Self.fullFormattingSources where typeNames.contains(read) && !richTypes.contains(storeAs) {
                guard let d = pb.data(forType: NSPasteboard.PasteboardType(read)), !d.isEmpty,
                      d.count <= Self.maxRichFormatBytes else { continue }
                formats.append(ClipFormat(type: storeAs, data: d))
                richTypes.insert(storeAs)
            }
            if imageSize == nil, let img = formats.first(where: { [ClipUTI.jpeg, ClipUTI.gif, ClipUTI.heic].contains($0.type) }),
               let px = ImageProbe.pixelSize(img.data) {
                imageSize = NSSize(width: px.width, height: px.height)
            }
        }
        if wants(ClipUTI.fileURL),
           let urls = pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            formats.append(ClipFormat(type: ClipUTI.fileURL, data: Data(urls.map(\.absoluteString).joined(separator: "\n").utf8)))
            fileNames = urls.map(\.lastPathComponent)
        }
        // Extra / custom types.
        for t in types {
            let raw = t.rawValue
            if Self.handledTypes.contains(raw) || Self.skipTypes.contains(raw) || richTypes.contains(raw) { continue }
            if all {
                if raw.hasPrefix("dyn.") || raw.hasPrefix("CorePasteboardFlavorType") || raw.hasPrefix("NeXT ")
                    || raw.hasPrefix("Apple ") { continue }
            } else if !enabled.contains(raw) { continue }
            if let d = pb.data(forType: t), !d.isEmpty { formats.append(ClipFormat(type: raw, data: d)) }
        }
        guard !formats.isEmpty else { return false }

        // Rich-only sources (RTFD from Notes, HTML-only web content): derive plain text for the description and
        // full-text search. RTF/RTFD are parsed by AppKit locally; HTML/web archives by DittoCore (no WebKit).
        if text == nil, fileNames.isEmpty,
           formats.contains(where: { ClipUTI.richTextTypes.contains($0.type) && $0.data.count <= Self.maxDeriveTextBytes }) {
            let parseable = formats.filter { $0.data.count <= Self.maxDeriveTextBytes }
            if let derived = PasteContent.derivedPlainText(from: parseable) {
                text = derived
                formats.insert(ClipFormat(type: ClipUTI.plainText, data: Data(derived.utf8)), at: 0)
            }
        }

        let maxBytes = settings.maxClipSizeBytes
        if maxBytes > 0 {
            // Over the total cap: drop full-formatting extras (largest first) before rejecting the clip.
            var total = formats.reduce(0) { $0 + $1.data.count }
            while total > maxBytes,
                  let idx = formats.indices.filter({ richTypes.contains(formats[$0].type) }).max(by: { formats[$0].data.count < formats[$1].data.count }) {
                total -= formats[idx].data.count
                formats.remove(at: idx)
            }
            if total > maxBytes { return false }
        }

        // Copy rules.
        let outcome = CopyRuleEngine.evaluate(rules: settings.copyRules, text: text, appBundleID: bundleID, appName: appName)
        if outcome.ignore && !force { return false }
        if let newText = outcome.text, newText != text, text != nil {
            text = newText
            // Rich formats no longer match the rewritten text.
            formats.removeAll { $0.type == ClipUTI.plainText || ClipUTI.richTextTypes.contains($0.type) }
            formats.insert(ClipFormat(type: ClipUTI.plainText, data: Data(newText.utf8)), at: 0)
        }
        if outcome.stripToPlain, text != nil {
            formats.removeAll { $0.type != ClipUTI.plainText }
        }

        let description = Self.makeDescription(text: text, fileNames: fileNames, imageSize: imageSize,
                                               formats: formats, maxChars: settings.descTextSize)

        // Destination group.
        var parentID = Ditto.topLevelParent
        if let cg = captureGroup {
            captureGroup = nil
            if cg.until > Date() { parentID = cg.id }
        }
        if parentID == Ditto.topLevelParent, let name = outcome.groupName {
            parentID = groupID(named: name)
        }

        var opts = ClipStore.AddOptions()
        opts.allowDuplicates = settings.allowDuplicates
        opts.allowBackToBackDuplicates = settings.allowBackToBackDuplicates
        opts.makeTopSticky = outcome.makeTopSticky
        opts.makeLastSticky = outcome.makeLastSticky
        opts.replaceTopSticky = outcome.replaceTopSticky

        let result: AddResult
        do {
            result = try state.store.addClip(formats: formats, description: description, sourceApp: bundleID.isEmpty ? appName : bundleID,
                                             parentID: parentID, options: opts)
        } catch {
            NSLog("DittoMac: failed to store clip: \(error)")
            return false
        }

        let clipID: Int64
        switch result {
        case .inserted(let id): clipID = id
        case .duplicateBumped(let id): clipID = id
        case .rejected: return false
        }
        if outcome.neverAutoDelete, var clip = try? state.store.clip(id: clipID), !clip.dontAutoDelete {
            clip.dontAutoDelete = true
            try? state.store.update(clip)
        }
        playSound()
        settings.recordCopy()
        if case .inserted = result { state.friends?.sendToAutoPeers(clipID: clipID) }
        state.clipsChanged()
        state.scheduleRetention?()
        return true
    }

    private func groupID(named name: String) -> Int64 {
        let trimmed = name.trimmingCharacters(in: .whitespaces)
        guard !trimmed.isEmpty else { return Ditto.topLevelParent }
        if let g = (try? state.store.groups())?.first(where: { $0.text.caseInsensitiveCompare(trimmed) == .orderedSame }) {
            return g.id
        }
        return (try? state.store.createGroup(name: trimmed, parentID: Ditto.topLevelParent)) ?? Ditto.topLevelParent
    }

    private func playSound() {
        let s = state.settings.playSoundOnCopy.trimmingCharacters(in: .whitespaces)
        guard !s.isEmpty else { return }
        if s.hasPrefix("/") {
            NSSound(contentsOfFile: s, byReference: true)?.play()
        } else {
            NSSound(named: NSSound.Name(s))?.play()
        }
    }

    /// Upstream: description = first N chars of text with leading whitespace stripped; files → "Copied File(s) - …".
    static func makeDescription(text: String?, fileNames: [String], imageSize: NSSize?, formats: [ClipFormat], maxChars: Int) -> String {
        // Finder also puts the file names on the pasteboard as text; files win (as upstream CF_HDROP).
        if !fileNames.isEmpty {
            return String(("Copied File(s) - " + fileNames.joined(separator: ", ")).prefix(max(maxChars, 20)))
        }
        if let t = text {
            let stripped = t.drop(while: { $0.isWhitespace || $0.isNewline })
            if !stripped.isEmpty { return String(stripped.prefix(maxChars)) }
        }
        if let sz = imageSize {
            return "Image (\(Int(sz.width)) × \(Int(sz.height)))"
        }
        return formats.first?.type ?? "Clip"
    }
}
